function markParty(s){document.querySelectorAll('.partySlot').forEach(el=>el.classList.toggle('active',el.dataset.who===s.partner));document.querySelectorAll('[data-pick]').forEach(b=>b.classList.toggle('on',b.dataset.pick===s.partner))}
function selectPartner(s,id,tapped){if(id===s.partner||!findCast(id))return;s.partner=id;const c=findCast(id);s.voice=c.voice||'';if(partyStages[id])stage=partyStages[id];save();markParty(s);const n=$('.chatHeader .name strong');if(n)n.textContent=c.name;if(tapped)toast(`Talking to ${c.name}.`)}
// How someone takes a shock, from who they are: 'calm' (doesn't flinch), 'scared' (panics) or 'surprised' (spins round).
// A quick guess from their persona right away; the AI brain refines it once and it is kept with the character.
function reactStyle(c){if(!c)return 'surprised';if(c.reactStyle)return c.reactStyle;const p=`${c.persona||''} ${c.role||''}`.toLowerCase();const g=/calm|steady|veteran|stoic|unflappable|cold|android|robot|seen it all|nothing scares|hunter|soldier|marine|captain/.test(p)?'calm':/nervous|jittery|anxious|timid|rookie|frightened|shy|child|kid|young|panic/.test(p)?'scared':'surprised';
  if(!c.reactAsked&&brainReady()){c.reactAsked=1;brain.write(state.brainCfg,[{role:'system',content:'Reply with exactly one word: calm, scared or surprised.'},{role:'user',content:`A loud, frightening sound goes off nearby. How does this character react? ${c.name}, ${c.role||''}. ${String(c.persona||'').slice(0,500)}`}],10).then(t=>{const w=String(t||'').toLowerCase().match(/calm|scared|surprised/);if(w){c.reactStyle=w[0];save()}}).catch(()=>{})}return g}
// Everyone present reacts to the same event in their own way, each with their own clip, a beat apart.
function reactAll(s){const who=partyOf(s)?Object.entries(partyStages):[[s.partner,stage]];for(const [id,st] of who){if(!st)continue;const style=reactStyle(findCast(id));if(style==='calm')continue;const clip=st.has(style)?style:st.has(style==='scared'?'surprised':'scared')?(style==='scared'?'surprised':'scared'):null;if(clip)setTimeout(()=>st.show(clip,{force:false}),120+Math.random()*600)}}
function partyReact(s,emotion){if(!/scared|surprised/.test(emotion))return;const who=Object.entries(partyStages).filter(([id])=>id!==s.partner);for(const [id,st] of who){const style=reactStyle(findCast(id));if(style==='calm')continue;if(st.has(style))setTimeout(()=>st.show(style,{force:false}),150+Math.random()*500)}}
