function portrait(c,cls=''){const src=mediaURL(c.image),loop=!src&&mediaURL(c.loop);return src?`<img class="${cls}" src="${esc(src)}" alt="${esc(c.name)}">`:loop?`<video class="${cls} loopPortrait" src="${esc(loop)}" muted playsinline autoplay loop aria-label="${esc(c.name)}"></video>`:`<div class="abstract ${cls}">${esc(c.name.slice(0,1))}</div>`}
