// Picking a character: chips for each group (yours, each world, each Homelancer faction) so the list stays short.
function pickGroups(list,selId,key='who'){const packOf={};for(const b of builtIn)if(b.pack)packOf[b.cast.id]=b.pack;
  const core=new Set(builtIn.filter(b=>!b.pack).map(b=>b.cast.id));
  const gOf=c=>{const p=packOf[c.id];if(!p)return core.has(c.id)?'core':'mine';if(p==='homelancer')return 'hl:'+(c.faction||'Other').split('·')[0].trim();return p};
  const names={core:'Main cast',mine:'Yours'};for(const w of WORLD_PACKS)names[w.id]=w.name;const groups=[];for(const c of list){const g=gOf(c);if(!groups.includes(g))groups.push(g)}
  const rank=g=>g==='core'?0:g==='mine'?1:2;groups.sort((a,b)=>rank(a)-rank(b)||a.localeCompare(b));
  const selG=selId&&list.find(c=>c.id===selId)?gOf(list.find(c=>c.id===selId)):null;state.pickG??={};let cur=state.pickG[key];if(!groups.includes(cur))cur=selG||groups[0];
  const label=g=>g.startsWith('hl:')?g.slice(3):names[g]||g;
  const chips=groups.length>1?`<div class="pickChips">${groups.map(g=>`<button class="mini ${g===cur?'on':''}" data-pickg="${esc(g)}" data-pickk="${key}">${esc(label(g))}</button>`).join('')}</div>`:'';
  return {chips,list:list.filter(c=>gOf(c)===cur)}}
