    const holo=box.querySelector('.gbHolo'),grip=box.querySelector('.gbMove');let down=null,moved=false;grip.addEventListener('pointerdown',e=>{const r=box.getBoundingClientRect();down={x:e.clientX,y:e.clientY,l:r.left,t:r.top,grip:1};moved=false;try{grip.setPointerCapture(e.pointerId)}catch{}});grip.addEventListener('pointermove',e=>{if(down)moveTo(down.l+e.clientX-down.x,down.t+e.clientY-down.y),moved=true});grip.addEventListener('pointerup',()=>{if(down&&moved){state.guidePos={x:box.offsetLeft/innerWidth,y:box.offsetTop/innerHeight};save()}down=null});holo.addEventListener('pointerdown',e=>{if(e.button)return;const r=box.getBoundingClientRect();down={x:e.clientX,y:e.clientY,l:r.left,t:r.top};moved=false;try{holo.setPointerCapture(e.pointerId)}catch{}});holo.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(!moved&&Math.hypot(dx,dy)<8)return;moved=true;moveTo(down.l+dx,down.t+dy)});const up=()=>{if(!down)return;down=null;if(moved){state.guidePos={x:box.offsetLeft/innerWidth,y:box.offsetTop/innerHeight};save()}else guideTalk()};holo.addEventListener('pointerup',up);holo.addEventListener('pointercancel',()=>{down=null});holo.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();guideTalk()}});
