  if($('#ambFromNormal'))$('#ambFromNormal').onclick=async()=>{const b=$('#ambFromNormal');b.disabled=true;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),buf=await ctx.decodeAudioData(await (await fetch(mediaURL(c.clips.normal))).arrayBuffer());ctx.close();let peak=0;const d=buf.getChannelData(0);for(let i=0;i<d.length;i+=50)peak=Math.max(peak,Math.abs(d[i]));if(peak<0.002)throw 0;c.ambient=c.clips.normal;save();again();toast('Using the sound from the Normal clip.')}catch{b.disabled=false;toast('The Normal clip has no sound to use.')}};
