  document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>copyText(forLook(b.dataset.prompt==='walkLoop'?walkClipPrompt('knee',scr):b.dataset.prompt==='approach'?walkClipPrompt('full',scr):clipPrompt(b.dataset.prompt,b.dataset.label,c.chroma==='blue'?'blue':'green'),c.look),`Prompt for ${b.dataset.label} copied. Paste it into your video generator with her picture.`));
